def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 r=json.loads((OUT/'report.json').read_text(encoding='utf-8'));a=json.loads((OUT/'independent_audit.json').read_text(encoding='utf-8'));assert a['passed'] and a['report_sha256']==sha(OUT/'report.json');s=r['summaries'];assert not r['preliminary_gate']
 refs=['runs/flyvis_brightness_gate_20261105/'+x for x in ('protocol.json','report.json','independent_audit.json')]
